SELECT cal.Date,cal.Month,COUNT(DISTINCT o.OrderID) OrdersCreated,COUNT(DISTINCT CASE WHEN l.UnpickedUnits>0 THEN o.OrderID END) UnpickedOrders,COUNT(CASE WHEN l.UnpickedUnits>0 THEN l.OrderLineID END) UnpickedLines,COALESCE(SUM(l.UnpickedUnits),0)::BIGINT UnpickedUnits,COALESCE(SUM(l.Quantity),0)::BIGINT OrderedUnits FROM analytics.calendar cal LEFT JOIN analytics.orders o ON o.OrderDate=cal.Date AND o.ScenarioID='base' LEFT JOIN analytics.order_lines l ON l.OrderID=o.OrderID AND l.ScenarioID='base' WHERE cal.Date<=DATE '2016-05-31' GROUP BY cal.Date,cal.Month ORDER BY cal.Date